const root=$input.first().json||{};
const p=root.project || root.input?.project || {};const workflows=root.workflows || root.input?.workflows || [];const credentials=root.credentials || root.input?.credentials || [];const tests=root.test_results || root.input?.test_results || [];const limitations=root.known_limitations || root.input?.known_limitations || [];
if(!p.name) return [{json:{success:false,component_id:'C6-F',component_version:'v1',error:{code:'MISSING_PROJECT_NAME',message:'project.name is required.'},next_action:'provide_project_metadata'}}];
const lines=a=>a.length?a.map(x=>`- ${x}`).join('
'):'- None recorded';
const workflowLines=workflows.length?workflows.map(w=>`- **${w.name||'Workflow'}** — ${w.purpose||'No purpose supplied'}; trigger: ${w.trigger||'not recorded'}; status: ${w.status||'not recorded'}`).join('
'):'- None recorded';
const credLines=credentials.length?credentials.map(c=>`- ${c.provider||c.name||'Credential'} — credential name: ${c.credential_name||'configure in n8n'}; required scopes/access: ${(c.required_access||[]).join(', ')||'not recorded'}`).join('
'):'- None recorded';
const testLines=tests.length?tests.map(t=>`- ${t.name||'Test'}: **${t.status||'unknown'}**${t.detail?` — ${t.detail}`:''}`).join('
'):'- None recorded';
const overview=`# ${p.name} — Automation Handoff

## Outcome
${p.outcome||'Not supplied'}

## Workflows
${workflowLines}

## Owner
${p.owner||'Not recorded'}
`;
const setup=`# Setup and Credentials

## Environment
${p.environment||'Client n8n instance'}

## Credential references
${credLines}

**Security:** secrets are configured in n8n Credentials or environment variables and are never included in this handoff pack.
`;
const testing=`# Test Record

${testLines}
`;
const maintenance='# Maintenance

- Review failed executions and retry queue regularly.
- Re-test provider credentials/scopes after credential rotation.
- Re-run mapping diagnostics after CRM/schema changes.
- Export a fresh workflow JSON after approved production changes.
- Keep scope changes separate from defect fixes.
';
const limits=`# Known Limitations

${lines(limitations.map(String))}
`;
return [{json:{success:true,component_id:'C6-F',component_version:'v1',handoff:{overview_md:overview,setup_md:setup,test_record_md:testing,maintenance_md:maintenance,known_limitations_md:limits},next_action:'deliver_handoff_pack',error:null}}];
